/* Server-backed workspace. Secrets and auth tokens never enter browser storage. */
var cloud={configured:false,user:null,data:null,strategyId:null,busy:false,filter:'all',error:null,accountId:null};
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},...(data?{body:JSON.stringify(data)}:{})});let d;try{d=await r.json()}catch{throw Error('Vercel 서버 API가 필요합니다.')}if(!r.ok){if(r.status===401&&path!=='auth')location.replace('/login.html');throw Error(d.error||'요청 실패');}return d;}
async function reloadCloud(){cloud.data=await api('workspace');if(!cloud.strategyId||!cloud.data.strategies.some(s=>s.id===cloud.strategyId))cloud.strategyId=cloud.data.strategies[0]?.id||null;}
async function cloudTask(fn){if(cloud.busy)return;cloud.busy=true;render();try{await fn();cloud.error=null}catch(e){toast(e.message);cloud.error=e.message}finally{cloud.busy=false;render()}}
const modeName=m=>({demo:'데모',testnet:'테스트넷',live:'실거래'}[m]||m);
const dt=v=>new Date(v).toLocaleString('ko-KR');
const cloudVersions=()=>cloud.data?.strategy_versions.filter(v=>v.mode===state.mode)||[];
const cloudTrades=()=>cloud.data?.trades.filter(t=>t.mode===state.mode)||[];
function currentApproval(){return cloud.data?.approvals.find(a=>a.mode===state.mode&&a.decision==='approved'&&!a.revoked_at&&new Date(a.expires_at)>new Date());}
function activeSession(){return cloud.data?.sessions.find(s=>s.mode===state.mode&&(s.state==='running'||s.paper_position));}
function cloudPlan(p){return `<div class="plan-grid">${[['대상',p.symbol+' · '+p.direction],['운용 자본',money(p.capital)+' USDT'],['레버리지',p.leverage+'× · 격리'],['1회 증거금',money(p.margin)+' USDT'],['최대 명목금액',money(p.margin*p.leverage)+' USDT'],['일일 손실 한도',money(p.dailyLoss)+' USDT'],['일일 거래 수',p.maxTrades+'회'],['유효 시간',p.validMinutes+'분'],['진입가',p.entryPrice??'미정'],['손절가',p.stopPrice??'미정'],['익절가',p.takeProfitPrice??'미정'],['조건 지원',p.executable?'고정 가격 조건':'검토용 · 자동 실행 미지원']].map(([k,v])=>`<div><span class="sub">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><p class="bubble plan-note">${esc(p.instructions)}</p>`}
function cloudCard(v){if(!v)return '<p class="sub">이전 운용안은 표시 범위를 벗어났습니다.</p>';const a=cloud.data.approvals.find(a=>a.strategy_version_id===v.id);const approved=a?.decision==='approved'&&!a.revoked_at&&new Date(a.expires_at)>new Date();return `<article class="strategy-card"><div class="row"><strong>${esc(v.plan.title)} · v${v.version}</strong><span class="badge">${approved?'승인 유효':a?.decision==='rejected'?'거절됨':a?'승인 만료·철회':'승인 대기'}</span></div>${cloudPlan(v.plan)}<p class="sub">${esc(v.model)} · ${dt(v.created_at)}<br>고정 버전 ${esc(v.plan_hash.slice(0,12))} · ${modeName(v.mode)}${a?'<br>승인 만료 '+dt(a.expires_at):''}</p><div class="plan-actions"><button class="btn primary" data-cloud-approve="${v.id}" ${cloud.busy||v.mode==='live'?'disabled':''}>이 버전 승인</button><button class="btn" data-cloud-edit="${v.id}">수정 요청</button><button class="btn" data-cloud-reject="${v.id}" ${cloud.busy?'disabled':''}>거절</button>${approved?`<button class="btn danger" data-cloud-revoke="${v.id}">승인 철회</button>`:''}</div></article>`}
const exchangeName=x=>x==='bitget'?'비트겟':'바이낸스';
const accounts=()=>cloud.data?.exchange_accounts||[];
function selectedAccount(mode=null){return accounts().find(a=>a.id===cloud.accountId&&(!mode||a.mode===mode))||accounts().find(a=>!mode||a.mode===mode)||null;}
function accountTitle(a){return a?`${exchangeName(a.exchange)} · ${a.label} · ${modeName(a.mode)}${a.account_type==='uta'?' · UTA':''}`:'계좌 없음';}
function accountSelect(id,list,chosen){return `<select id="${id}" aria-label="조회 계좌">${list.map(a=>`<option value="${a.id}" ${chosen?.id===a.id?'selected':''}>${esc(accountTitle(a))}</option>`).join('')||'<option value="">등록된 계좌 없음</option>'}</select>`;}
function runnerOnline(accountId){const r=cloud.data?.runner.find(r=>r.account_id===accountId&&!r.revoked_at&&new Date(r.expires_at)>new Date());return !!(r?.last_seen&&Date.now()-new Date(r.last_seen).getTime()<90000);}
function cloudConnections(){const a=selectedAccount();return `<section class="panel connection"><h2>비공개 워크스페이스</h2><p class="sub">사이트 비밀번호로 접속합니다. 전략·승인·매매 기록은 Supabase에 보관합니다.</p>${cloud.user?`<div class="connection-card"><span>${esc(cloud.user.email)}</span><button class="btn" id="cloud-logout">로그아웃</button></div><div class="connection-card"><div><h2>AI 전략 대화</h2><p class="sub">OpenAI: ${esc(cloud.data?.models.openai||'모델 ID 미설정')}<br>Gemini: ${esc(cloud.data?.models.gemini||'모델 ID 미설정')}</p></div><span class="badge">서버 호출</span></div><div class="divider"></div><h2>거래 계좌 · 조회 전용</h2><p class="sub">바이낸스·비트겟의 여러 계좌를 각각 등록합니다. 키와 비트겟 Passphrase는 PC에만 보관합니다. 현재 실제 주문은 잠겨 있습니다.</p><form id="account-form" class="account-form"><label>계좌 이름<input name="label" maxlength="60" placeholder="예: 비트겟 메인" required></label><label>거래소<select name="exchange" id="account-exchange"><option value="bitget">비트겟</option><option value="binance">바이낸스</option></select></label><label>비트겟 계정 유형<select name="accountType" id="account-type"><option value="classic">일반 선물 (Classic)</option><option value="uta">통합계정 (UTA)</option></select></label><label>환경<select name="mode"><option value="live">실계좌 · 조회만</option><option value="testnet">테스트넷 / 비트겟 모의계좌</option></select></label><button class="btn primary" ${cloud.busy?'disabled':''}>계좌 추가</button></form>${accounts().map(account=>{const snap=cloud.data.account_snapshots.find(s=>s.account_id===account.id);return `<div class="connection-card"><div><strong>${esc(accountTitle(account))}</strong><p class="sub">${snap?'USDT 잔고 '+money(snap.balance)+' · 미실현 '+signed(Number(snap.unrealized_pnl))+' · '+dt(snap.created_at):'계좌 데이터 수신 대기'}</p></div><span class="badge">${runnerOnline(account.id)?'온라인':'오프라인'}</span></div>`}).join('')}<div class="divider"></div><label>연결 토큰을 발급할 계좌${accountSelect('connection-account',accounts(),a)}</label><button class="btn" id="pair-runner" ${cloud.busy||!a?'disabled':''}>이 계좌의 24시간 연결 토큰 발급</button> <button class="btn danger" id="revoke-runner" ${!a?'disabled':''}>이 계좌 연결 폐기</button><div id="runner-token" class="token-box" hidden></div><p class="sub">재발급·폐기는 선택한 계좌에만 적용됩니다. 다른 계좌의 연결은 유지됩니다.</p><div class="divider"></div><button class="btn" id="cloud-refresh">서버 데이터 새로고침</button><p class="sub">각 계좌는 별도의 실행기로 동시에 조회할 수 있습니다. 이번 버전은 주문·실거래 내역 수집·계좌별 전략 자동 실행을 지원하지 않습니다.</p>`:`<p class="sub">이메일이나 Supabase 계정 없이 사이트 비밀번호로 접속합니다.</p><a class="btn primary" href="/login.html">비밀번호 입력 화면으로</a>`}</section>`;}
function cloudStrategy(){const d=cloud.data;const msgs=d.messages.filter(m=>m.strategy_id===cloud.strategyId&&m.mode===state.mode).slice().reverse();const a=currentApproval();const s=activeSession();return `<div class="banner">${modeName(state.mode)} 전략 대화 · 제안은 승인 전까지 효력이 없습니다. ${state.mode==='demo'?'모의 체결은 고정 시나리오이며 실제 시세가 아닙니다.':'현재 계좌 조회 전용이며 주문 실행은 잠겨 있습니다.'}</div><div class="strategy-toolbar"><label>전략<select id="strategy-select">${d.strategies.map(s=>`<option value="${s.id}" ${cloud.strategyId===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><button class="btn" id="new-strategy">+ 새 전략</button><label>대화 모델<select id="provider-select"><option value="openai">OpenAI · ${esc(d.models.openai||'설정 필요')}</option><option value="gemini">Gemini · ${esc(d.models.gemini||'설정 필요')}</option></select></label></div><div class="strategy-layout"><section class="panel chat-panel strategy-chat"><div class="panel-head"><h2>전략 대화 · 버전 관리</h2><span class="badge">Supabase 저장</span></div><div class="chat-messages">${msgs.length?msgs.map(m=>`<div class="message ${m.role==='user'?'user':''}"><div><div class="name">${m.role==='user'?'나':'AI'}<span class="time">${dt(m.created_at)}</span></div><div class="bubble">${esc(m.content)}</div></div></div>${m.strategy_version_id?cloudCard(d.strategy_versions.find(v=>v.id===m.strategy_version_id)):''}`).join(''):'<div class="empty sub">전략을 만들고 원하는 조건을 이야기하세요.<br>수치와 가격을 직접 지정하거나 AI에게 제안을 요청할 수 있습니다.</div>'}</div><form class="composer" id="cloud-chat"><div class="input-box"><textarea id="cloud-message" maxlength="4000" aria-label="AI 전략 메시지" placeholder="예: 운용 자본 100 USDT. BTC 롱 전략의 금액과 레버리지를 제안해줘." ${cloud.busy?'disabled':''}></textarea><div class="input-bottom"><span>${cloud.busy?'AI 응답·서버 저장 중…':'채팅 → 새 버전 → 카드 승인'}</span><button class="send" aria-label="AI 메시지 전송" ${cloud.busy||!cloud.strategyId?'disabled':''}>↑</button></div></div></form></section><aside class="panel strategy-controls"><div class="panel-head"><h2>운용 승인</h2><span class="badge">${modeName(state.mode)}</span></div><div class="right-body"><h2>${s?.state==='running'?'모의 실행 중':a?'승인 완료':'승인 대기'}</h2><p class="sub">${a?esc(cloud.data.strategy_versions.find(v=>v.id===a.strategy_version_id)?.plan.title||'승인 운용안')+' · 유효기간 '+dt(a.expires_at):'운용안 카드에서 수치·가격·설명을 확인하고 승인하세요.'}</p><div class="divider"></div><button class="btn primary wide" id="cloud-start" ${!a||cloud.busy||state.mode!=='demo'?'disabled':''}>승인한 버전으로 모의 실행</button><button class="btn wide" id="cloud-step" ${!s||cloud.busy||state.mode!=='demo'?'disabled':''}>다음 모의 단계</button><button class="btn danger wide" id="cloud-stop" ${!s||cloud.busy?'disabled':''}>모의 실행 중지 · 모의 포지션 종료</button><p class="sub">시작 시 서버에서 승인 해시·유효기간·모드를 재검사합니다. 데모는 손절 가격 감시를 재현하지 않는 고정 시나리오입니다. 테스트넷·실거래 자동 주문은 후속 통합 검증이 필요합니다.</p></div></aside></div>`}
function cloudDesk(){const ts=cloudTrades(),net=ts.reduce((s,t)=>s+Number(t.net_pnl),0),account=selectedAccount(state.mode);const snap=cloud.data.account_snapshots.find(s=>s.mode===state.mode&&s.account_id===account?.id);const sess=activeSession();const a=currentApproval();return `<div class="banner">${modeName(state.mode)} · ${state.mode==='demo'?'서버에 저장되는 고정 모의 시나리오':'계좌 조회 전용 · 주문 잠김'}${snap?' · 계좌 수신 '+dt(snap.created_at):''}</div>${state.mode!=='demo'?`<div class="strategy-toolbar"><label>조회 계좌${accountSelect('desk-account',accounts().filter(a=>a.mode===state.mode),account)}</label></div>`:''}<div class="metrics">${[['USDT 지갑 잔고',state.mode==='demo'?'—':snap?money(snap.balance):'—'],['완료 거래 순손익',state.mode==='demo'?signed(net):'—'],['미실현 손익',state.mode==='demo'?(sess?.paper_position?money((sess.paper_position.mark-sess.paper_position.entry)*sess.paper_position.quantity*(cloud.data.strategy_versions.find(v=>v.id===sess.strategy_version_id).plan.direction==='LONG'?1:-1)):'0.00'):snap?money(snap.unrealized_pnl):'—'],['완료 거래',state.mode==='demo'?ts.length:'—']].map(([k,v])=>`<div class="metric"><label>${k}</label><div class="value">${v}</div><p class="sub">${state.mode==='demo'?'모의 데이터':esc(account?.label||'계좌 미선택')}</p></div>`).join('')}</div><div class="monitor-grid"><section class="panel"><div class="panel-head"><h2>${state.mode==='demo'?'승인된 운용안':'조회 계좌'}</h2><span class="badge">${state.mode==='demo'?(a?'승인 유효':'대기'):account?exchangeName(account.exchange):'미선택'}</span></div><div class="right-body">${state.mode==='demo'?(a?cloudPlan(cloud.data.strategy_versions.find(v=>v.id===a.strategy_version_id).plan):'<div class="empty sub">전략 관리에서 대화를 시작하세요.</div>'):`<h2>${esc(accountTitle(account))}</h2><p class="sub">USDT 지갑 잔고와 USDT 선물 포지션을 표시합니다. UTA의 다른 담보 코인·현물 전체 자산을 합산한 금액은 아닙니다. 실제 거래 내역 수집과 계좌별 전략 실행은 아직 연결되지 않았습니다.</p><p class="sub">${runnerOnline(account?.id)?'실행기 온라인':'실행기 오프라인'}</p>`}</div></section><section class="panel"><div class="panel-head"><h2>포지션 상태</h2><span class="badge">${modeName(state.mode)}</span></div><div class="right-body">${state.mode==='demo'?sess?.paper_position?`<p>모의 진입가 ${money(sess.paper_position.entry)}</p><p>모의 현재가 ${money(sess.paper_position.mark)}</p>`:'<div class="empty sub">모의 포지션 없음</div>':snap?`<p class="sub">${Date.now()-new Date(snap.created_at)>90000?'오래된 계좌 데이터 · 연결 확인 필요':'최근 수신 계좌'}</p>${snap.positions.map(p=>`<div class="connection-card"><span>${esc(p.symbol)} · ${Number(p.quantity)<0?'SHORT':'LONG'} · ${esc(Math.abs(Number(p.quantity)))}</span><span>${signed(p.unrealizedPnl)} USDT</span></div>`).join('')||'<div class="empty sub">포지션 없음</div>'}`:'<div class="empty sub">실행기에서 계좌 데이터 수신 대기</div>'}</div></section></div>`;}
function cloudHistory(){const rows=cloudTrades().filter(t=>cloud.filter==='all'||t.strategy_version_id===cloud.filter);return `<section class="panel section"><div class="panel-head"><h2>${modeName(state.mode)} 매매 기록 · 일지</h2><button class="btn" id="cloud-export">CSV 내보내기</button></div><div class="right-body"><label>전략 버전 <select id="history-version"><option value="all">전체</option>${cloudVersions().map(v=>`<option value="${v.id}" ${cloud.filter===v.id?'selected':''}>${esc(v.plan.title)} · v${v.version}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>종료 시각</th><th>전략 버전</th><th>종목 / 방향</th><th>진입 → 종료</th><th>수수료 / 펀딩 수입</th><th>순손익</th><th>매매 일지</th></tr></thead><tbody>${rows.length?rows.map(t=>{const v=cloud.data.strategy_versions.find(v=>v.id===t.strategy_version_id),j=cloud.data.journal_entries.find(j=>j.trade_id===t.id);return `<tr><td>${dt(t.closed_at)}</td><td>${esc(v?.plan.title||'알 수 없음')} · v${v?.version||'?'}</td><td>${esc(t.symbol)} ${esc(t.side)}</td><td>${money(t.entry_price)} → ${money(t.exit_price)}</td><td>${money(t.fees)} / ${signed(Number(t.funding))}</td><td>${signed(Number(t.net_pnl))}</td><td><button class="btn" data-journal="${t.id}">${j?'일지 수정':'일지 작성'}</button>${j?`<p class="sub">${esc(j.notes.slice(0,90))}</p>`:''}</td></tr>`}).join(''):'<tr><td colspan="7" class="empty">저장된 매매가 없습니다.</td></tr>'}</tbody></table></div><div id="journal-editor"></div></section>`}
function cloudPerformance(){return `<section class="panel section"><div class="panel-head"><h2>전략 버전별 실적 · ${modeName(state.mode)}</h2><span class="badge">전체 저장 거래 집계</span></div><p class="sub" style="padding:20px">순손익 = 실현 손익 − 수수료 + 펀딩 수입. 승률은 순손익이 양수인 완료 거래 기준입니다. 모의·테스트넷·실거래를 분리합니다.</p><div class="table-wrap"><table><thead><tr><th>전략</th><th>버전</th><th>완료 거래</th><th>승률</th><th>순손익</th><th>수수료</th><th>펀딩 수입</th><th>Profit factor</th></tr></thead><tbody>${cloud.data.strategy_performance.filter(r=>r.mode===state.mode).map(r=>`<tr><td>${esc(r.title)}</td><td>v${r.version}</td><td>${r.trades}</td><td>${r.win_rate===null?'—':money(r.win_rate)+'%'}</td><td>${signed(Number(r.net_pnl))}</td><td>${money(r.fees)}</td><td>${signed(Number(r.funding))}</td><td>${r.profit_factor===null?'—':money(r.profit_factor)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">전략 채팅에서 운용안 버전을 만들면 여기에 표시됩니다.</td></tr>'}</tbody></table></div></section>`}
function cloudPage(){if(!cloud.data)return `<section class="panel connection"><h2>서버 데이터 로드 실패</h2><p class="sub">${esc(cloud.error||'잠시 후 다시 시도하세요.')}</p><button class="btn" id="cloud-refresh">다시 불러오기</button><button class="btn" id="cloud-logout">로그아웃</button></section>`;return (state.page==='strategy'?cloudStrategy():state.page==='history'?cloudHistory():state.page==='performance'?cloudPerformance():state.page==='connections'?cloudConnections():state.page==='logs'?`<section class="panel connection"><h2>저장된 세션</h2>${cloud.data.sessions.filter(s=>s.mode===state.mode).map(s=>`<div class="connection-card"><span>${dt(s.created_at)}</span><span>${esc(s.state)}</span></div>`).join('')||'<p class="sub">세션 없음</p>'}</section>`:cloudDesk());}
function bindCloud(){
 if($('#cloud-logout'))$('#cloud-logout').onclick=()=>cloudTask(async()=>{await api('auth',{action:'logout'});cloud.user=null;cloud.data=null;cloud.strategyId=null;location.replace('/login.html');});
 if($('#cloud-refresh'))$('#cloud-refresh').onclick=()=>cloudTask(reloadCloud);
 if($('#new-strategy'))$('#new-strategy').onclick=()=>{const title=prompt('새 전략 이름');if(title)cloudTask(async()=>{const r=await api('workspace',{action:'createStrategy',title});cloud.strategyId=r.result[0].id;await reloadCloud();});};
 if($('#strategy-select'))$('#strategy-select').onchange=e=>{cloud.strategyId=e.target.value;render();};
 if($('#cloud-chat')){$('#cloud-chat').onsubmit=e=>{e.preventDefault();const message=$('#cloud-message').value.trim(),provider=$('#provider-select').value;if(message)cloudTask(async()=>{await api('chat',{strategyId:cloud.strategyId,mode:state.mode,message,provider});await reloadCloud();});};$('#cloud-message').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#cloud-chat').requestSubmit();}};}
 for(const decision of ['approve','reject','revoke'])document.querySelectorAll('[data-cloud-'+decision+']').forEach(b=>b.onclick=()=>cloudTask(async()=>{const v=cloud.data.strategy_versions.find(v=>v.id===b.getAttribute('data-cloud-'+decision));await api('workspace',{action:'decision',versionId:v.id,planHash:v.plan_hash,decision});await reloadCloud();}));
 document.querySelectorAll('[data-cloud-edit]').forEach(b=>b.onclick=()=>{const v=cloud.data.strategy_versions.find(v=>v.id===b.dataset.cloudEdit);$('#cloud-message').value=`운용안 v${v.version}을 바탕으로 수정해줘. 변경 사항: `;$('#cloud-message').focus();});
 for(const [id,command] of [['cloud-start','start'],['cloud-step','paperStep'],['cloud-stop','stop']])if($('#'+id))$('#'+id).onclick=()=>cloudTask(async()=>{const approvalId=command==='start'?currentApproval()?.id:activeSession()?.approval_id;if(approvalId)await api('workspace',{action:'session',approvalId,command});await reloadCloud();});
 for(const id of ['connection-account','desk-account'])if($('#'+id))$('#'+id).onchange=e=>{cloud.accountId=e.target.value;render();};
 if($('#account-exchange'))$('#account-exchange').onchange=e=>{$('#account-type').disabled=e.target.value==='binance';};
 if($('#account-form'))$('#account-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);cloudTask(async()=>{const r=await api('workspace',{action:'createAccount',label:f.get('label'),exchange:f.get('exchange'),accountType:f.get('accountType'),mode:f.get('mode')});cloud.accountId=r.result[0].id;await reloadCloud();});};
 if($('#pair-runner'))$('#pair-runner').onclick=async()=>{if(cloud.busy)return;const account=selectedAccount();if(!account)return;cloud.busy=true;$('#pair-runner').disabled=true;$('#connection-account').disabled=true;try{const r=await api('workspace',{action:'pairRunner',accountId:account.id});await reloadCloud();render();const box=$('#runner-token');if(box){box.hidden=false;box.textContent=`${accountTitle(account)}\n계좌 ID: ${r.accountId}\n연결 토큰 (이번 화면에서만 표시): ${r.token}\n만료: ${dt(r.expiresAt)}\n실행기 옵션: --exchange ${r.exchange} --account-type ${r.accountType} --mode ${r.mode} --account ${r.accountId}`;}}catch(e){toast(e.message)}finally{cloud.busy=false;if($('#pair-runner'))$('#pair-runner').disabled=false;if($('#connection-account'))$('#connection-account').disabled=false;}};
 if($('#revoke-runner'))$('#revoke-runner').onclick=()=>{const account=selectedAccount();if(account)cloudTask(async()=>{await api('workspace',{action:'revokeRunner',accountId:account.id});await reloadCloud();});};
 if($('#history-version'))$('#history-version').onchange=e=>{cloud.filter=e.target.value;render();};
 document.querySelectorAll('[data-journal]').forEach(b=>b.onclick=()=>{const j=cloud.data.journal_entries.find(j=>j.trade_id===b.dataset.journal);$('#journal-editor').innerHTML=`<form class="right-body" id="journal-form"><h2>매매 복기</h2><label>메모<textarea name="notes" maxlength="6000" rows="6" required>${esc(j?.notes||'')}</textarea></label><label>태그 (쉼표로 구분)<input name="tags" value="${esc((j?.tags||[]).join(', '))}" maxlength="300"></label><button class="btn primary">일지 저장</button></form>`;$('#journal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);cloudTask(async()=>{await api('workspace',{action:'journal',tradeId:b.dataset.journal,notes:f.get('notes'),tags:f.get('tags').split(',').map(t=>t.trim()).filter(Boolean)});await reloadCloud();});};});
 if($('#cloud-export'))$('#cloud-export').onclick=()=>{const rows=cloudTrades().filter(t=>cloud.filter==='all'||t.strategy_version_id===cloud.filter);const safe=v=>'"'+String(v??'').replace(/^[=+@\t\r-]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff시각,모드,전략버전ID,종목,방향,진입가,종료가,수량,실현손익,수수료,펀딩수입,순손익,일지\n'+rows.map(t=>[t.closed_at,t.mode,t.strategy_version_id,t.symbol,t.side,t.entry_price,t.exit_price,t.quantity,t.gross_pnl,t.fees,t.funding,t.net_pnl,cloud.data.journal_entries.find(j=>j.trade_id===t.id)?.notes||''].map(safe).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`tradingchat-${state.mode}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
document.addEventListener('DOMContentLoaded',async()=>{try{const r=await api('auth');cloud.configured=r.configured;cloud.user=r.user;if(cloud.user)await reloadCloud();}catch(e){cloud.error=e.message}render();});

function switchCloudMode(mode){if(!['demo','testnet','live'].includes(mode))return;return cloudTask(async()=>{const s=activeSession();if(s)await api('workspace',{action:'session',approvalId:s.approval_id,command:'stop'});const a=currentApproval();if(a){await api('workspace',{action:'decision',versionId:a.strategy_version_id,planHash:a.plan_hash,decision:'revoke'});}state.mode=mode;cloud.filter='all';await reloadCloud();toast(modeName(mode)+' 모드로 전환했습니다.');});}

setInterval(async()=>{if(!cloud.user||cloud.busy||!['desk','logs','performance'].includes(state.page))return;try{await reloadCloud();render();}catch(e){cloud.error=e.message;}},30000);
